function renderCity() { const rightbar = document.querySelector(".rightbar"); if (rightbar && $("cityHub") && $("cityHub").parentElement !== rightbar) rightbar.prepend($("cityHub")); const city = cities.find(item => item.id === state.city) || cities[0]; const english = state.language === "en"; $("cityName").textContent = english ? city.nameEn : city.name; $("cityDescription").textContent = english ? city.descriptionEn : city.description; $("cityIndex").textContent = `${String(cities.indexOf(city) + 1).padStart(2, "0")} / ${String(cities.length).padStart(2, "0")}`; $("cityTabs").innerHTML = cities.map(item => `<button class="city-tab ${item.id === city.id ? "active" : ""}" data-city="${item.id}">${english ? item.nameEn : item.name}</button>`).join(""); $("cityServices").innerHTML = `<span class="city-service ${city.color}">${english ? city.marketEn : city.market}</span>${(english ? city.servicesEn : city.services).map(service => `<span class="city-service">${service}</span>`).join("")}<button class="city-service dungeon-service" data-dungeon="${city.id}">⬡ ${english ? city.dungeonEn : city.dungeon}</button>`; document.querySelectorAll("[data-city]").forEach(button => button.addEventListener("click", () => changeCity(button.dataset.city))); document.querySelectorAll("[data-dungeon]").forEach(button => button.addEventListener("click", () => enterDungeon(button.dataset.dungeon))); }
