function useVendingMachine(action) { state.vendingCredit = state.vendingCredit || 0; if (action === "coin") { if (state.credits < 25) return toast("Credits 不足"); state.credits -= 25; state.vendingCredit = 25; state.vendingAnimation = "coin"; addFeed("飲料機吞入 ₡25，指示燈開始閃爍。", "warn"); toast("投幣成功 // 請取貨"); } else if (action === "dispense" && state.vendingCredit >= 25) { state.vendingCredit = 0; state.vendingAnimation = "dispense"; const rewards = [{ text: "霓虹能量飲 // RAM +20", apply: () => { state.ram = clamp(state.ram + 20, 0, 100); } }, { text: "冷卻汽水 // HEAT -6", apply: () => { state.heat = clamp(state.heat - 6, 0, 100); } }, { text: "維生果凍 // VITAL +18", apply: () => { state.hp = clamp(state.hp + 18, 0, 100 + (state.upgrades.includes("plating") ? 15 : 0)); } }, { text: "幸運代幣 // ₡45", apply: () => { state.credits += 45; } }]; const reward = rewards[Math.floor(Math.random() * rewards.length)]; reward.apply(); addFeed(`飲料機掉出：${reward.text}。`, "warn"); toast(reward.text); } else return; saveState(); render(); }
function syncVendingControls() { const stateLabel = $("vendingState"); const coin = document.querySelector("[data-vending=coin]"); const dispense = document.querySelector("[data-vending=dispense]"); const machine = document.querySelector(".vending-game"); if (!stateLabel || !coin || !dispense) return; const credit = state.vendingCredit || 0; stateLabel.textContent = `投幣槽：₡${credit} / 25`; coin.disabled = credit >= 25; dispense.disabled = credit < 25; if (machine && state.vendingAnimation) { machine.dataset.animation = state.vendingAnimation; setTimeout(() => { state.vendingAnimation = ""; render(); }, 900); } }
function renderVendingMachineArt() { const game = document.querySelector(".vending-game"); if (!game || game.querySelector(".vending-machine-art")) return; const art = document.createElement("div"); art.className = "vending-machine-art"; art.innerHTML = `<svg viewBox="0 0 240 260" role="img" aria-label="霓虹飲料機"><defs><linearGradient id="machineFront" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#18353b"/><stop offset=".58" stop-color="#102029"/><stop offset="1" stop-color="#0a1119"/></linearGradient><linearGradient id="machineSide" x1="0" x2="1"><stop stop-color="#25213a"/><stop offset=".45" stop-color="#151326"/><stop offset="1" stop-color="#05070d"/></linearGradient><linearGradient id="machineTop" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ff4f96" stop-opacity=".9"/><stop offset="1" stop-color="#3de5d0" stop-opacity=".7"/></linearGradient><linearGradient id="glassReflection" x1="0" x2="1"><stop stop-color="#fff" stop-opacity=".18"/><stop offset=".35" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#3de5d0" stop-opacity=".12"/></linearGradient><filter id="machineShadow"><feGaussianBlur stdDeviation="7"/></filter></defs><ellipse cx="132" cy="244" rx="96" ry="12" fill="#000" opacity=".7" filter="url(#machineShadow)"/><path d="M47 36 78 18h124l-42 18z" fill="url(#machineTop)" stroke="#3de5d0" stroke-width="2"/><path d="M160 36h42v190l-42 17z" fill="url(#machineSide)" stroke="#ff4f96" stroke-width="2"/><path d="M160 43h34M160 54h34M160 65h34M160 76h34M160 87h34M160 98h34M160 109h34" stroke="#3de5d0" stroke-width="2" opacity=".32"/><path d="M47 36h113v207H47z" fill="url(#machineFront)" stroke="#3de5d0" stroke-width="2"/><path class="vending-screen" d="M58 51h91v68H58z" fill="#070d16" stroke="#ff4f96" stroke-width="2"/><path d="M67 103h72M67 92h72M67 81h72M67 70h72" stroke="#3de5d0" stroke-width="3" opacity=".6"/><path d="M70 60h48" stroke="#ffba5c" stroke-width="3" opacity=".8"/><path d="M58 135h91v47H58z" fill="#0a1119" stroke="#263746"/><rect class="vending-product" x="68" y="145" width="20" height="29" rx="3" fill="#ff4f96" opacity=".75"/><rect x="95" y="145" width="20" height="29" rx="3" fill="#3de5d0" opacity=".75"/><rect x="122" y="145" width="17" height="29" rx="3" fill="#ffba5c" opacity=".75"/><circle cx="76" cy="200" r="15" fill="#151326" stroke="#ffba5c" stroke-width="3"/><path d="M76 191v18M67 200h18" stroke="#ffba5c" stroke-width="3"/><circle class="vending-coin-light" cx="125" cy="200" r="10" fill="#080c13" stroke="#3de5d0" stroke-width="3"/><path d="M118 200h14" stroke="#3de5d0" stroke-width="3"/><path class="vending-chute" d="M58 222h91" stroke="#b7ec63" stroke-width="4"/><path d="M47 36v207" stroke="#fff" stroke-opacity=".3" stroke-width="2"/><path d="M202 36v190" stroke="#ff4f96" stroke-width="3" opacity=".8"/><path d="M54 43h99v192H54z" fill="url(#glassReflection)" opacity=".35"/></svg><button class="machine-coin-slot" type="button" data-vending="coin" aria-label="投入 25 Credits">₡</button><span class="machine-label">NEON//DRINKS</span>`; game.prepend(art); art.querySelector("[data-vending=coin]").addEventListener("click", () => useVendingMachine("coin")); }
