function useCityActivity(id) { if (state.combat) return toast("先完成目前戰鬥"); const city = state.city; const maxHp = 100 + (state.upgrades.includes("plating") ? 15 : 0); let reward = ""; if (id === "vending") { if (state.credits < 25) return toast("Credits 不足"); state.credits -= 25; if (Math.random() < .55) { state.hp = clamp(state.hp + 10, 0, maxHp); reward = "VITAL +10"; } else { state.ram = clamp(state.ram + 12, 0, 100); reward = "RAM +12"; } } else if (id === "arcade") { if (state.credits < 40) return toast("Credits 不足"); state.credits -= 40; const payout = 20 + Math.floor(Math.random() * 81); state.credits += payout; state.xp += 12; reward = `+₡${payout} // +12 XP`; } else if (id === "signalScan") { spawnNextContract("訊號掃描站已鎖定新目標"); return; } else if (id === "medbay") { if (state.credits < 60) return toast("Credits 不足"); state.credits -= 60; state.hp = clamp(state.hp + 35, 0, maxHp); state.heat = clamp(state.heat - 4, 0, 100); reward = "VITAL +35 // HEAT -4"; } else if (id === "salvage") { if (state.credits < 30) return toast("Credits 不足"); state.credits -= 30; if (Math.random() < .5) { state.inventory.loot += 1; reward = "黑盒 ×1"; } else { state.inventory.medkit += 1; reward = "體素針 ×1"; } } else if (id === "pitFight") { if (state.credits < 20) return toast("Credits 不足"); state.credits -= 20; state.credits += 45 + Math.floor(Math.random() * 80); state.xp += 20; state.rep += 1; state.heat = clamp(state.heat + 5, 0, 100); reward = "+Credits // +20 XP // REP +1"; } else if (id === "memoryDive") { if (state.credits < 70) return toast("Credits 不足"); state.credits -= 70; const action = generateCombatAction(); reward = `${action.title} // Combat Action`; } else if (id === "casino") { if (state.credits < 50) return toast("Credits 不足"); state.credits -= 50; const payout = Math.random() < .42 ? 150 + Math.floor(Math.random() * 251) : 0; state.credits += payout; reward = payout ? `+₡${payout}` : "空手離場 // 再試一次"; } else if (id === "anomaly") { if (state.credits < 30) return toast("Credits 不足"); state.credits -= 30; const action = generateCombatAction(); reward = `${action.title} // 異常已收容`; } else return; state.xp = state.xp || 0; addFeed(`${city.toUpperCase()} 活動完成：${reward}。`, "warn"); toast(reward); saveState(); render(); }
function changeCity(id) { if (state.combat || state.city === id) return; state.city = id; const city = cities.find(item => item.id === id); state.contract = ""; addFeed(`你搭上夜班線，前往 ${state.language === "en" ? city.nameEn : city.name}。`, "warn"); spawnNextContract("新城市的訊號已接入"); saveState(); render(); }
function enterDungeon(id) { if (state.combat) return; const city = cities.find(item => item.id === id); const dungeon = { id: `dungeon-${id}-${Date.now()}`, city: id, tag: "DUNGEON // DEEP", title: `${city.name}：${city.dungeon}`, desc: `深入 ${city.name} 的禁區，帶回只在地下才會發光的核心。`, enemy: "DUNGEON WARDEN", hp: 260, reward: 900, xp: 180, difficulty: "★★★" }; contracts.push(dungeon); state.contract = dungeon.id; addFeed(`${city.dungeon} 已開放。這次沒有撤離保證。`, "warn"); saveState(); render(); $("combatPanel").scrollIntoView({ behavior: "smooth", block: "center" }); }
function openDungeonChallenge(id) { if (state.combat) return; const city = cities.find(item => item.id === id); let panel = $("dungeonChallenge"); if (!panel) { panel = document.createElement("div"); panel.id = "dungeonChallenge"; panel.className = "dungeon-challenge"; $("cityActivities").after(panel); } panel.innerHTML = `<div class="activity-heading"><b>${city.dungeon} // ENTRY PROTOCOL</b><small>先完成一個小遊戲，再進入地下城</small></div><p>選擇入侵方式：不同路線會改變初始 Energy、敵方 HP 與獎勵。</p><div class="challenge-options"><button data-dungeon-route="hack"><b>⌁ 破解</b><small>敵方 HP -20% // 初始 Energy -1</small></button><button data-dungeon-route="stealth"><b>◌ 潛行</b><small>敵方 HP -10% // Heat -8</small></button><button data-dungeon-route="force"><b>ϟ 強攻</b><small>獎勵 +35% // 敵方傷害 +5</small></button></div>`; panel.querySelectorAll("[data-dungeon-route]").forEach(button => button.addEventListener("click", () => startDungeonAfterChallenge(id, button.dataset.dungeonRoute))); panel.scrollIntoView({ behavior: "smooth", block: "center" }); }
function startDungeonAfterChallenge(id, route) { const city = cities.find(item => item.id === id); const modifiers = { hack: { hp: .8, energy: 2, reward: 1, heat: 0 }, stealth: { hp: .9, energy: 3, reward: 1.15, heat: -8 }, force: { hp: 1, energy: 3, reward: 1.35, heat: 5 } }[route]; const dungeon = { id: `dungeon-${id}-${Date.now()}`, city: id, tag: "DUNGEON // DEEP", title: `${city.name}：${city.dungeon}`, desc: `你選擇${route === "hack" ? "破解" : route === "stealth" ? "潛行" : "強攻"}路線深入禁區。`, enemy: "DUNGEON WARDEN", hp: Math.round(260 * modifiers.hp), reward: Math.round(900 * modifiers.reward), xp: 180, difficulty: "★★★", dungeonEnergy: modifiers.energy, dungeonRoute: route }; contracts.push(dungeon); state.contract = dungeon.id; state.heat = clamp(state.heat + modifiers.heat, 0, 100); addFeed(`${city.dungeon} 入場協議完成：${route.toUpperCase()}。`, "warn"); $("dungeonChallenge")?.remove(); saveState(); render(); startMission(); $("combatPanel").scrollIntoView({ behavior: "smooth", block: "center" }); }
function renderFeed() { $("feed").innerHTML = state.feed.map(row => `<div class="feed-row ${row.type}"><span class="feed-time">${row.time}</span><span><b>${row.type === "warn" ? "WARN //" : "SYS //"}</b> ${row.text}</span></div>`).join(""); }
function renderCombatActions() { const panel = $("combatPanel"); if (!panel) return; const actions = panel.querySelector(".combat-actions"); const catalog = availableCombatActions().map(action => action.id === "hack" && state.equipment?.DECK === "deck-ghost" ? { ...action, cost: 1, hint: "1 能量 // 破防 // GHOSTLINK" } : action); let loadout = (state.combatLoadout || defaultState.combatLoadout).filter(id => catalog.some(action => action.id === id)); catalog.slice(0, 6).forEach(action => { if (!loadout.includes(action.id)) loadout.push(action.id); }); state.combatLoadout = loadout.slice(0, 6); let heading = $("combatActionHeading"); if (!heading) { heading = document.createElement("div"); heading.id = "combatActionHeading"; heading.className = "combat-skill-heading"; actions.parentElement.insertBefore(heading, actions); } let picker = $("combatActionPicker"); if (!picker) { picker = document.createElement("div"); picker.id = "combatActionPicker"; picker.className = "combat-skill-picker"; picker.hidden = true; actions.parentElement.insertBefore(picker, actions); } heading.innerHTML = `<span>COMBAT ACTIONS // 可自由更換</span><select id="combatSlotSelect" aria-label="選擇要更換的戰鬥技能欄位"><option value="0">SLOT 1</option><option value="1">SLOT 2</option><option value="2">SLOT 3</option><option value="3">SLOT 4</option><option value="4">SLOT 5</option><option value="5">SLOT 6</option></select><button type="button" id="swapCombatActions">更換技能</button>`; actions.innerHTML = state.combatLoadout.map((id, index) => { const action = catalog.find(item => item.id === id); return `<button class="action-btn ${action.className}" data-action="${action.id}" data-cost="${action.cost || ""}" data-combat-slot="${index}"><b>${action.icon} ${action.title}</b><small>${action.hint}</small></button>`; }).join(""); picker.innerHTML = catalog.map(action => `<button type="button" data-config-action="${action.id}">${action.icon} ${action.title}<small>${action.hint}</small></button>`).join(""); $("swapCombatActions").addEventListener("click", () => { picker.hidden = !picker.hidden; }); picker.querySelectorAll("[data-config-action]").forEach(button => button.addEventListener("click", () => { const slot = Number($("combatSlotSelect").value); const actionId = button.dataset.configAction; const oldIndex = state.combatLoadout.indexOf(actionId); if (oldIndex >= 0 && oldIndex !== slot) [state.combatLoadout[slot], state.combatLoadout[oldIndex]] = [state.combatLoadout[oldIndex], state.combatLoadout[slot]]; else state.combatLoadout[slot] = actionId; picker.hidden = true; addFeed(`${catalog.find(action => action.id === actionId).title} 已裝入戰鬥 SLOT ${slot + 1}。`, "warn"); saveState(); render(); })); actions.querySelectorAll("[data-action]").forEach(button => button.addEventListener("click", () => combatAction(button.dataset.action))); }
function renderCombatLoadoutOverview() { const node = $("combatLoadoutOverview"); if (!node) return; const catalog = availableCombatActions().map(action => action.id === "hack" && state.equipment?.DECK === "deck-ghost" ? { ...action, cost: 1, hint: "1 能量 // 破防 // GHOSTLINK" } : action); const loadout = state.combatLoadout || defaultState.combatLoadout; node.innerHTML = loadout.map((id, index) => { const action = catalog.find(item => item.id === id); const options = catalog.map(option => `<option value="${option.id}" ${option.id === id ? "selected" : ""}>${option.icon} ${option.title}</option>`).join(""); return `<div class="loadout-slot combat-action-slot"><div class="loadout-slot-head"><span>SLOT ${index + 1}</span><b>已裝備</b></div><select class="loadout-select" data-combat-slot="${index}" aria-label="選擇戰鬥 SLOT ${index + 1}">${options}</select><small>${action.hint}</small></div>`; }).join(""); node.querySelectorAll("[data-combat-slot]").forEach(select => select.addEventListener("change", () => { const slot = Number(select.dataset.combatSlot); const actionId = select.value; const oldIndex = loadout.indexOf(actionId); if (oldIndex >= 0 && oldIndex !== slot) [loadout[slot], loadout[oldIndex]] = [loadout[oldIndex], loadout[slot]]; else loadout[slot] = actionId; addFeed(`${catalog.find(action => action.id === actionId).title} 已裝入戰鬥 SLOT ${slot + 1}。`, "warn"); saveState(); render(); })); }
function renderCombatConsumables() { const panel = $("combatPanel"); if (!panel) return; const actions = panel.querySelector(".combat-actions"); let box = $("combatConsumables"); if (!box) { box = document.createElement("div"); box.id = "combatConsumables"; box.className = "combat-consumables"; actions.after(box); } const combat = state.combat; box.innerHTML = `<div class="consumable-heading"><b>CONSUMABLES</b><small>消耗品 // 不佔用 Combat Action SLOT</small></div><div class="consumable-list"><button class="consumable-btn medkit" data-combat-consumable="medkit" ${!combat || combat.busy || state.inventory.medkit < 1 || combat.energy < 1 ? "disabled" : ""}><span>＋</span><b>體素針</b><small>治療 +25</small><em>×${state.inventory.medkit}</em></button><button class="consumable-btn medbox" data-combat-consumable="medbox" ${!combat || combat.busy || state.inventory.medbox < 1 || combat.energy < 2 ? "disabled" : ""}><span>▣</span><b>醫療箱</b><small>治療 +55</small><em>×${state.inventory.medbox}</em></button></div>`; box.querySelectorAll("[data-combat-consumable]").forEach(button => button.addEventListener("click", () => useCombatConsumable(button.dataset.combatConsumable))); }
function useCombatConsumable(id) { const combat = state.combat; if (!combat || combat.busy) return; const config = { medkit: { cost: 1, amount: 25, label: "體素針" }, medbox: { cost: 2, amount: 55, label: "醫療箱" } }[id]; if (!config || state.inventory[id] < 1) return toast(`沒有${config?.label || "這項物品"}`); if (combat.energy < config.cost) return toast("能量不足，無法使用消耗品"); const maxHp = 100 + (state.upgrades.includes("plating") ? 15 : 0); combat.energy -= config.cost; state.inventory[id] -= 1; state.hp = clamp(state.hp + config.amount, 0, maxHp); combat.combo = 0; combat.busy = true; combat.log = `${config.label}使用成功，VITAL +${config.amount}。你失去連擊。`; saveState(); render(); setTimeout(() => enemyTurn(`consumable:${id}`), 420); }
function renderCombat() { const c = state.combat; const panel = $("combatPanel"); renderCombatActions(); renderCombatConsumables(); if (!c) { panel.classList.remove("active"); return } const mission = contracts.find(x => x.id === state.contract); if (!mission) { state.combat = null; panel.classList.remove("active"); addFeed("目前合約已失效，戰鬥已安全中止。", "warn"); return } c.enemyMax = Number(c.enemyMax) || mission.hp; c.enemyHp = clamp(Number(c.enemyHp) || c.enemyMax, 0, c.enemyMax); c.turn = Number(c.turn) || 1; c.energy = clamp(Number(c.energy) || 3, 0, 3); c.combo = Number(c.combo) || 0; c.status = c.status || ""; c.statusTurns = Number(c.statusTurns) || 0; c.guard = Boolean(c.guard); panel.classList.add("active"); $("enemyName").textContent = mission.enemy; $("turnNumber").textContent = String(c.turn).padStart(2, "0"); $("enemyHpText").textContent = `${c.enemyHp} / ${c.enemyMax}`; $("enemyHpBar").style.width = `${clamp(c.enemyHp / c.enemyMax * 100, 0, 100)}%`; $("combatLog").textContent = c.log || "選擇你的行動。"; $("combatState").textContent = c.guard ? "GHOST SHIELD" : c.status ? `${c.status.toUpperCase()} // ${c.statusTurns}` : `ENERGY ${c.energy}/3`; $("energyText").textContent = `${c.energy} / 3`; $("energyBar").style.width = `${c.energy / 3 * 100}%`; document.querySelectorAll("[data-action]").forEach(button => button.disabled = c.busy || (button.dataset.cost && Number(button.dataset.cost) > c.energy)); }
function addFeed(text, type = "") { const time = new Date().toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" }); state.feed.unshift({ time, text, type }); state.feed = state.feed.slice(0, 7); renderFeed(); }
function createSignalContract() { const city = cities.find(item => item.id === state.city) || cities[0]; const template = generatedMissions[Math.floor(Math.random() * generatedMissions.length)]; const prefix = signalPrefixes[Math.floor(Math.random() * signalPrefixes.length)]; const location = signalLocations[Math.floor(Math.random() * signalLocations.length)]; const target = signalTargets[Math.floor(Math.random() * signalTargets.length)]; const enemy = signalEnemies[Math.floor(Math.random() * signalEnemies.length)]; const difficulty = ["★☆☆", "★★☆", "★★★"][Math.floor(Math.random() * 3)]; const scale = difficulty === "★★★" ? 1.25 : difficulty === "★★☆" ? 1 : .82; return { id: `signal-${Date.now()}-${generatedContractId++}`, city: city.id, tag: "NEW // SIGNAL", title: `${prefix}：${target}`, desc: `訊號鎖定於 ${location}。${template.desc} [${city.nameEn}]`, enemy, hp: Math.round(template.hp * scale), reward: Math.round(template.reward * scale), xp: Math.round(template.xp * scale), difficulty }; }
function spawnNextContract(reason = "") { const contract = createSignalContract(); contracts.push(contract); localStorage.setItem("neonpunk-contracts", JSON.stringify(contracts.filter(item => item.id.startsWith("signal-")))); state.contract = contract.id; nextSignalAt = Date.now() + 90000; addFeed(`${contract.title} 出現在街區訊號中。${reason}`, "warn"); render(); saveState(); toast(`新合約已接入 // ${contract.title}`); }
function toast(text) { const node = $("toast"); node.textContent = text; node.classList.add("show"); setTimeout(() => node.classList.remove("show"), 2400) }
function startMission() { if (!currentUser) { openLogin(); toast("請先登入，才能開始同步任務"); return } if (state.combat) { $("combatPanel").scrollIntoView({ behavior: "smooth", block: "center" }); return } const mission = contracts.find(c => c.id === state.contract); state.combat = { enemyHp: mission.hp, enemyMax: mission.hp, turn: 1, energy: mission.dungeonEnergy || 3, combo: 0, busy: false, guard: false, status: "", statusTurns: 0, log: `${mission.enemy} 擋住了出口。先觀察它的節奏。` }; addFeed(`${mission.title} 已進入接觸距離。`); render(); $("combatPanel").scrollIntoView({ behavior: "smooth", block: "center" }); }
function combatAction(action) { const c = state.combat; if (!c || c.busy) return; const maxHp = 100 + (state.upgrades.includes("plating") ? 15 : 0); const costs = { strike: 0, hack: state.equipment.DECK === "deck-ghost" ? 1 : 2, overdrive: 3, medkit: 1, guard: 1, shockwave: 2, bloodhack: 2 }; const cost = costs[action] || 0; if (c.energy < cost) { toast("能量不足，先用斬擊或防守"); return } if (action === "medkit" && state.inventory.medkit < 1) { toast("沒有體素針，去黑市補貨"); return } c.energy -= cost; let damage = 0; if (action === "strike") { c.combo++; const comboBonus = state.equipment.WEAPON === "knife-arc" ? (c.combo >= 2 ? 12 : 0) : (c.combo >= 3 ? 12 : 0); damage = 18 + Math.floor(Math.random() * 10) + (state.equipment.WEAPON === "knife-mono" ? 10 : 0) + comboBonus + (c.combo >= 3 && state.equippedSkills.includes("echo") ? 16 : 0); c.log = c.combo >= 3 ? `連擊 ${c.combo}！你抓到它的攻擊間隔。` : `斬擊命中 ${damage} 傷害。`; } if (action === "hack") { if (state.ram < 20) { toast("RAM 不足"); c.energy += cost; return } state.ram -= 20; c.status = "jammed"; c.statusTurns = 2; damage = 30 + Math.floor(Math.random() * 16) + (state.upgrades.includes("blackice") ? 18 : 0); if (state.equippedSkills.includes("parasite")) state.hp = clamp(state.hp + 8, 0, maxHp); c.log = `ICEBREAK 撕開防火牆，造成 ${damage} 傷害。`; } if (action === "overdrive") { damage = 48 + Math.floor(Math.random() * 20) + (state.upgrades.includes("redline") ? 20 : 0); c.combo = 0; c.status = "burning"; c.statusTurns = 2; c.log = `超載脈衝貫穿敵方核心，造成 ${damage} 傷害。`; } if (action === "shockwave") { damage = 28 + Math.floor(Math.random() * 12); c.status = "jammed"; c.statusTurns = 1; c.combo = 0; c.log = `震盪波命中，造成 ${damage} 傷害並打斷反擊。`; } if (action === "bloodhack") { damage = 20 + Math.floor(Math.random() * 10); state.hp = clamp(state.hp + 12, 0, maxHp); c.combo = 0; c.log = `血脈駭入造成 ${damage} 傷害，回復 12 VITAL。`; } if (action === "medkit") { state.inventory.medkit -= 1; state.hp = clamp(state.hp + 25, 0, maxHp); c.combo = 0; c.log = "體素針灌入血管。你失去連擊，但活著。"; } if (action === "guard") { c.guard = true; c.combo = 0; c.log = "幽靈外套展開。下一次反擊傷害減半。"; } if (action === "escape") { state.heat = clamp(state.heat + (state.equippedSkills.includes("phase") ? 0 : 12), 0, 100); state.combat = null; addFeed("你切斷連線，帶著未完成的合約消失。", "warn"); saveState(); render(); return } if (damage) c.enemyHp = Math.max(0, c.enemyHp - damage); if (c.enemyHp <= 0) { finishMission(); return } c.busy = true; render(); setTimeout(() => enemyTurn(action), 420); }
const baseCombatAction = combatAction;
combatAction = function (action) { const generated = (state.generatedCombatActions || []).find(item => item.id === action); if (generated) { const c = state.combat; if (!c || c.busy) return; const cost = generated.cost || 2; if (c.energy < cost) return toast("能量不足，先用斬擊或防守"); c.energy -= cost; const maxHp = 100 + (state.upgrades.includes("plating") ? 15 : 0); const damage = generated.damage ? generated.damage + Math.floor(Math.random() * 9) - 4 : 0; if (damage) c.enemyHp = Math.max(0, c.enemyHp - damage); if (generated.heal) state.hp = clamp(state.hp + generated.heal, 0, maxHp); c.status = generated.damage ? "jammed" : c.status; c.statusTurns = generated.damage ? 1 : c.statusTurns; c.combo = 0; c.log = `${generated.title} ${damage ? `造成 ${damage} 傷害` : `回復 ${generated.heal} VITAL`}。`; if (c.enemyHp <= 0) return finishMission(); c.busy = true; render(); setTimeout(() => enemyTurn(action), 420); return } if (action !== "medbox") return baseCombatAction(action); const c = state.combat; if (!c || c.busy) return; if (c.energy < 2) return toast("能量不足，醫療箱需要 2 能量"); if (state.inventory.medbox < 1) return toast("沒有醫療箱，去黑市補貨"); const maxHp = 100 + (state.upgrades.includes("plating") ? 15 : 0); c.energy -= 2; state.inventory.medbox -= 1; state.hp = clamp(state.hp + 55, 0, maxHp); c.combo = 0; c.busy = true; c.log = "醫療箱展開，止血泡沫封住傷口。你失去連擊，但恢復了 55 VITAL。"; render(); setTimeout(() => enemyTurn(action), 420); };
function enemyTurn(action) { const c = state.combat; if (!c) return; let hit = 8 + Math.floor(Math.random() * 13) + (state.heat >= 80 ? 5 : state.heat >= 55 ? 2 : 0); if (c.guard) { hit = Math.ceil(hit * (state.equipment.COAT === "coat-ghost" ? .4 : .5)); c.guard = false; } if (c.status === "jammed") hit = Math.max(2, hit - 6); state.hp = Math.max(0, state.hp - hit); state.heat = clamp(state.heat + Math.max(0, (action === "hack" ? 4 : 2) - (state.equipment.COAT === "coat-rain" ? 2 : 0)), 0, 100); c.statusTurns -= 1; if (c.statusTurns <= 0) c.status = ""; c.energy = Math.min(3, c.energy + 1); c.turn++; c.busy = false; c.log = `敵方反擊 ${hit} 傷害。能量回充，輪到你了。`; if (state.hp <= 0) { state.hp = 35; const loss = state.equippedSkills.includes("decoy") ? Math.floor(state.credits * .5) : 120; state.credits = Math.max(0, state.credits - loss); state.heat = clamp(state.heat + 20, 0, 100); state.combat = null; addFeed("你在巷口醒來，裝備被剝走一部分。", "warn"); showResult("defeat", "你被擊倒了", `敵方反擊 ${hit} 傷害。你在巷口醒來，少了 ₡${loss}。`, `-₡${loss} // VITAL 35`); } saveState(); render(); }
function finishMission() { const mission = contracts.find(x => x.id === state.contract); const lootFound = 1 + Math.floor(Math.random() * 2); const actionFound = Math.random() < .35 ? generateCombatAction() : null; state.completedContracts = [...new Set([...(state.completedContracts || []), mission.id])]; state.credits += mission.reward; state.xp += mission.xp; state.rep += 3; state.inventory.loot += lootFound; state.heat = clamp(state.heat + 8, 0, 100); while (state.xp >= state.level * 100 - 40) { state.xp -= state.level * 100 - 40; state.level++; } state.combat = null; addFeed(`${mission.title} 完成。你從 ${mission.enemy} 身上拆下 ${lootFound} 個黑盒戰利品。${actionFound ? `訊號殘骸生成了新的 Combat Action：${actionFound.title}。` : ""}`); showResult("success", "目標已擊敗", `${mission.enemy} 的訊號歸零。任務已從 active 清單移除。`, `+₡${mission.reward} // +${mission.xp} XP // ◆ ×${lootFound}${actionFound ? ` // ✦ ${actionFound.title}` : ""}`); spawnNextContract("你的選擇引來另一個委託人。"); }
function buyUpgrade(id) { const item = upgrades.find(u => u.id === id); if (!item || state.credits < item.cost || state.upgrades.includes(id)) return; state.credits -= item.cost; state.upgrades.push(id); if (id === "neural") state.ram = 100; if (id === "plating") state.hp = 115; state.installLog.push({ icon: item.icon, title: item.title, time: new Date().toLocaleDateString("en-GB") }); addFeed(`${item.title} 已安裝。你的身體發出微弱的嗡鳴。`); toast(`${item.title} // INSTALLED`); saveState(); render(); }
function learnSkill(id) { const skill = skillCatalog.find(item => item.id === id); if (!skill || state.skills.includes(id) || state.credits < skill.price) return; state.credits -= skill.price; state.skills.push(id); if (state.equippedSkills.length < 2) state.equippedSkills.push(id); addFeed(`${skill.title} 技能晶片已解密。你的戰鬥習慣改變了。`); toast(`${skill.title} // DECRYPTED`); saveState(); render(); }
function openLootBox() { if (state.inventory.loot < 1) return; state.inventory.loot -= 1; const unknownSkills = skillCatalog.filter(skill => !state.skills.includes(skill.id)); const unknownActions = combatActionCatalog.filter(action => action.price && !state.combatActions.includes(action.id)); const roll = Math.random(); let reward; if (roll < .2 && unknownSkills.length) { const skill = unknownSkills[Math.floor(Math.random() * unknownSkills.length)]; state.skills.push(skill.id); if (state.equippedSkills.length < 2) state.equippedSkills.push(skill.id); reward = `${skill.icon} ${skill.title} // Neural Skill 已解密`; addFeed(`黑盒裂開，取得 Neural Skill：${skill.title}。`); } else if (roll < .38 && unknownActions.length) { const action = unknownActions[Math.floor(Math.random() * unknownActions.length)]; state.combatActions.push(action.id); reward = `${action.icon} ${action.title} // Combat Action 已解鎖`; addFeed(`黑盒裂開，取得 Combat Action：${action.title}。`); } else if (roll < .56) { const credits = 120 + Math.floor(Math.random() * 181); state.credits += credits; reward = `₡${credits} // 冷錢包入帳`; addFeed(`黑盒裡找到一枚企業代幣。`); } else if (roll < .72) { state.inventory.medkit += 2; reward = `體素針 ×2 // 醫療補給`; addFeed(`黑盒裡的體素針還沒過期。`); } else if (roll < .86) { state.inventory.medbox += 1; reward = `醫療箱 ×1 // 重型醫療補給`; addFeed(`黑盒內藏著一只未拆封的醫療箱。`); } else if (roll < .94) { state.inventory.ramCell += 1; state.ram = 100; reward = `RAM 電池 ×1 // RAM 已回充`; addFeed(`黑盒裡傳出一次短促的藍光。`); } else { state.inventory.loot += 1; state.heat = clamp(state.heat - 8, 0, 100); reward = `冷卻零件 // HEAT -8 // 黑盒保留`; addFeed(`黑盒裡是一枚冷卻零件，讓你的訊號暫時降溫。`); } showResult("success", "黑盒已解密", "這次的戰利品不只一種。", reward); toast(reward); saveState(); render(); }
function learnCombatAction(id) { const action = combatActionCatalog.find(item => item.id === id); if (!action || state.combatActions.includes(id) || state.credits < action.price) return; state.credits -= action.price; state.combatActions.push(id); addFeed(`${action.title} Combat Action 已解鎖，可裝入任一 SLOT。`); toast(`${action.title} // UNLOCKED`); saveState(); render(); }
function tradeMarket(id) { if (id === "openLoot") { openLootBox(); return; } if (id === "sellLoot" && state.inventory.loot > 0) { state.inventory.loot -= 1; state.credits += 140; addFeed("你把黑盒交給了無名買家。沒有問它裡面是誰。", "warn"); toast("戰利品售出 +₡140"); } else if (id.startsWith("combat:")) { learnCombatAction(id.slice(7)); return; } else if (id.startsWith("skill:")) { learnSkill(id.slice(6)); return; } else if (id.startsWith("sellSkill:")) { const skillId = id.slice(10); state.skills = state.skills.filter(skill => skill !== skillId); state.equippedSkills = state.equippedSkills.filter(skill => skill !== skillId); const skill = skillCatalog.find(item => item.id === skillId); state.credits += Math.floor(skill.price * .45); addFeed(`${skill.title} 技能晶片轉賣給了另一名 Runner。`, "warn"); toast(`技能售出 +₡${Math.floor(skill.price * .45)}`); } else { const item = marketItems.find(entry => entry.id === id); if (!item || state.credits < item.price) return; state.credits -= item.price; state.inventory[item.id] += 1; if (id === "ramCell") state.ram = 100; addFeed(`${item.title} 已藏進你的外套內袋。`); toast(`${item.title} // PURCHASED`); } saveState(); render(); }
