function saveState() { localStorage.setItem("neonpunk-save", JSON.stringify(state)); $("saveState").textContent = currentUser ? "CLOUD SYNCING" : "LOGIN REQUIRED"; if (currentUser && database) set(ref(database, `neonpunk/${currentUser.uid}`), { ...state, lastSaved: Date.now() }).then(() => $("saveState").textContent = "CLOUD SAVED").catch(() => $("saveState").textContent = "CLOUD ERROR"); }
