$("continueBtn").addEventListener("click", startMission); $("valuesBtn").addEventListener("click", () => { renderValues(); $("valuesModal").hidden = false; }); $("closeValues").addEventListener("click", () => $("valuesModal").hidden = true); $("renameBtn").addEventListener("click", () => { $("nameInput").value = state.name; $("renameModal").hidden = false; $("nameInput").focus(); }); $("closeRename").addEventListener("click", () => $("renameModal").hidden = true); $("renameForm").addEventListener("submit", event => { event.preventDefault(); const name = $("nameInput").value.trim().replace(/[<>]/g, ""); if (!name) return; state.name = name; $("renameModal").hidden = true; addFeed(`Runner ID 已更新為 ${name}。`); toast(`${name} // IDENTITY UPDATED`); saveState(); render(); }); document.querySelectorAll("[data-action]").forEach(button => button.addEventListener("click", () => combatAction(button.dataset.action))); $("saveBtn").addEventListener("click", () => { saveState(); toast(currentUser ? "進度已同步" : "請登入後同步進度") }); $("loginBtn").addEventListener("click", () => currentUser ? signOut(auth) : openLogin()); $("closeLogin").addEventListener("click", () => $("loginModal").hidden = true); $("resultClose").addEventListener("click", () => $("resultModal").hidden = true); $("switchAuth").addEventListener("click", setLoginMode); $("loginForm").addEventListener("submit", submitAuth); $("clearFeed").addEventListener("click", () => { state.feed = []; saveState(); renderFeed(); }); setInterval(() => { const now = Date.now(); $("clock").textContent = new Date(now).toLocaleTimeString("en-GB"); const remaining = Math.max(0, nextSignalAt - now); const seconds = Math.ceil(remaining / 1000); $("artClock").textContent = `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`; if (!state.combat && now - lastHeatTick >= 10000) { state.heat = clamp(state.heat - 1, 0, 100); lastHeatTick = now; render(); } if (!state.combat && remaining <= 0) spawnNextContract("自動刷新"); }, 1000); render(); connectFirebase();
